cypress_script:
describe('Floating Navigation Menu Links', () => {
  it('should remain on the page when clicking on Home link', () => {
    cy.visit('https://the-internet.herokuapp.com/floating_menu');
    cy.get('a').contains('Home').click();
    cy.url().should('eq', 'https://the-internet.herokuapp.com/floating_menu');
    cy.get('#menu').should('be.visible');
  });
  it('should remain on the page when clicking on News link', () => {
    cy.visit('https://the-internet.herokuapp.com/floating_menu');
    cy.get('a').contains('News').click();
    cy.url().should('eq', 'https://the-internet.herokuapp.com/floating_menu');
    cy.get('#menu').should('be.visible');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';
test.describe('Floating Navigation Menu Links', () => {
  test('should remain on the page when clicking on Home link', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/floating_menu');
    await page.click('a:text("Home")');
    await expect(page).toHaveURL('https://the-internet.herokuapp.com/floating_menu');
    await expect(page.locator('#menu')).toBeVisible();
  });
  test('should remain on the page when clicking on News link', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/floating_menu');
    await page.click('a:text("News")');
    await expect(page).toHaveURL('https://the-internet.herokuapp.com/floating_menu');
    await expect(page.locator('#menu')).toBeVisible();
  });
});
